using System.ComponentModel;
using System.Globalization;
using System.Text;
namespace TiendaMascotasHuevos;
public sealed class MainForm : Form {
    readonly SqliteStore store;
    readonly TabControl tabs=new(){Dock=DockStyle.Fill};
    readonly DataGridView products=Grid(),clients=Grid(),sales=Grid(),cart=Grid();
    readonly BindingList<CartRow> cartRows=new();
    readonly ComboBox productPicker=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=260};
    readonly ComboBox clientPicker=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=260};
    readonly ComboBox payPicker=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=130};
    readonly NumericUpDown quantity=new(){Minimum=1,Maximum=10000,Value=1,Width=70};
    readonly Label totalLabel=new(){AutoSize=true,Font=new Font("Segoe UI",14,FontStyle.Bold)};
    sealed record Choice(int Id,string Text){public override string ToString()=>Text;}
    public sealed class CartRow {public int ProductoId{get;set;}public string Producto{get;set;}="";public int Cantidad{get;set;}public decimal Precio{get;set;}public decimal Subtotal=>Cantidad*Precio;}
    static DataGridView Grid()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,AllowUserToAddRows=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Color.White};
    static Button Btn(string text,Action click){var b=new Button{Text=text,AutoSize=true,Padding=new Padding(9,5,9,5),Margin=new Padding(4)};b.Click+=(_,_)=>{try{click();}catch(Exception ex){MessageBox.Show(ex.Message,"Aviso",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};return b;}
    static FlowLayoutPanel Bar()=>new(){Dock=DockStyle.Top,Height=58,FlowDirection=FlowDirection.LeftToRight,Padding=new Padding(8),AutoScroll=true};
    static TabPage Page(string name,Control grid,FlowLayoutPanel bar){var page=new TabPage(name);page.Controls.Add(grid);page.Controls.Add(bar);return page;}
    public MainForm(SqliteStore store){this.store=store;Text="Comercio | Arena para gatos y cajas de huevos";Width=1150;Height=750;MinimumSize=new Size(850,550);Font=new Font("Segoe UI",10);Controls.Add(tabs);Build();RefreshAll();}
    void Build(){
        var pb=Bar();pb.Controls.Add(Btn("Nuevo producto",()=>EditProduct(null)));pb.Controls.Add(Btn("Editar producto",()=>EditProduct(Selected<Producto>(products))));pb.Controls.Add(Btn("Ajustar stock",Adjust));pb.Controls.Add(Btn("Actualizar",RefreshAll));tabs.TabPages.Add(Page("Productos e inventario",products,pb));
        var cb=Bar();cb.Controls.Add(Btn("Nuevo cliente",()=>EditClient(null)));cb.Controls.Add(Btn("Editar cliente",()=>EditClient(Selected<Cliente>(clients))));cb.Controls.Add(Btn("Actualizar",RefreshAll));tabs.TabPages.Add(Page("Clientes",clients,cb));
        var vb=Bar();vb.Controls.Add(new Label{Text="Producto",AutoSize=true,Margin=new Padding(4,12,3,0)});vb.Controls.Add(productPicker);vb.Controls.Add(new Label{Text="Cantidad",AutoSize=true,Margin=new Padding(5,12,3,0)});vb.Controls.Add(quantity);vb.Controls.Add(Btn("Añadir",AddCart));vb.Controls.Add(Btn("Quitar seleccionado",RemoveCart));
        var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=95,AutoScroll=true,Padding=new Padding(10)};bottom.Controls.Add(new Label{Text="Cliente",AutoSize=true,Margin=new Padding(4,12,3,0)});bottom.Controls.Add(clientPicker);bottom.Controls.Add(new Label{Text="Pago",AutoSize=true,Margin=new Padding(5,12,3,0)});payPicker.Items.AddRange(new object[]{"Efectivo","Débito","Crédito","Transferencia"});payPicker.SelectedIndex=0;bottom.Controls.Add(payPicker);bottom.Controls.Add(totalLabel);bottom.Controls.Add(Btn("Confirmar venta",Checkout));
        cart.DataSource=cartRows;var vp=new TabPage("Nueva venta");vp.Controls.Add(cart);vp.Controls.Add(bottom);vp.Controls.Add(vb);tabs.TabPages.Add(vp);
        var sb=Bar();sb.Controls.Add(Btn("Ver comprobante",ShowReceipt));sb.Controls.Add(Btn("Exportar ventas CSV",ExportCsv));sb.Controls.Add(Btn("Actualizar",RefreshAll));tabs.TabPages.Add(Page("Historial de ventas",sales,sb));
        var help=new TextBox{Multiline=true,ReadOnly=true,Dock=DockStyle.Fill,ScrollBars=ScrollBars.Vertical,Text="SISTEMA DE VENTAS Y STOCK\r\n\r\n1. Registre productos con código único, precio y stock.\r\n2. Registre clientes o use Consumidor final.\r\n3. Añada productos al carrito y confirme la venta.\r\n4. La venta descuenta stock en una transacción SQLite.\r\n5. Revise comprobantes e historial y exporte CSV.\r\n\r\nLos precios son ejemplos en CLP. La opción comprobante genera un documento interno NO tributario. Para boletas electrónicas oficiales se requiere integración autorizada con SII.\r\n\r\nDatos guardados en AppData\\Local\\TiendaMascotasHuevos\\tienda.db"};tabs.TabPages.Add(new TabPage("Ayuda"){Controls={help}});
    }
    static T? Selected<T>(DataGridView grid) where T:class => grid.CurrentRow?.DataBoundItem as T;
    void RefreshAll(){products.DataSource=store.Listar(false).ToList();clients.DataSource=store.ListarClientes().ToList();sales.DataSource=store.ListarVentas().ToList();productPicker.Items.Clear();foreach(var p in store.Listar().Where(x=>x.Stock>0))productPicker.Items.Add(new Choice(p.Id,$"{p.Nombre} · {p.Presentacion} · ${p.Precio:N0} ({p.Stock})"));if(productPicker.Items.Count>0)productPicker.SelectedIndex=0;clientPicker.Items.Clear();clientPicker.Items.Add(new Choice(0,"Consumidor final"));foreach(var c in store.ListarClientes())clientPicker.Items.Add(new Choice(c.Id,c.Nombre));clientPicker.SelectedIndex=0;UpdateTotal();}
    void AddCart(){if(productPicker.SelectedItem is not Choice choice)throw new InvalidOperationException("Seleccione un producto.");var p=store.Listar().First(x=>x.Id==choice.Id);var old=cartRows.FirstOrDefault(x=>x.ProductoId==p.Id);int count=(int)quantity.Value;if((old?.Cantidad??0)+count>p.Stock)throw new InvalidOperationException("Cantidad superior al stock disponible.");if(old!=null){old.Cantidad+=count;cartRows.ResetBindings();}else cartRows.Add(new CartRow{ProductoId=p.Id,Producto=p.Nombre,Cantidad=count,Precio=p.Precio});UpdateTotal();}
    void RemoveCart(){if(Selected<CartRow>(cart) is {} row)cartRows.Remove(row);UpdateTotal();}
    void UpdateTotal()=>totalLabel.Text=$"Total: ${cartRows.Sum(x=>x.Subtotal):N0}   ";
    void Checkout(){if(cartRows.Count==0)throw new InvalidOperationException("El carrito está vacío.");int? client=((Choice)clientPicker.SelectedItem!).Id is var id && id>0?id:null;var v=new NuevaVenta(client,payPicker.Text,cartRows.Select(x=>(x.ProductoId,x.Cantidad)).ToList());if(MessageBox.Show($"Confirmar venta por ${cartRows.Sum(x=>x.Subtotal):N0}?","Confirmación",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;var saleId=store.Registrar(v);cartRows.Clear();RefreshAll();MessageBox.Show($"Venta #{saleId} registrada correctamente.");tabs.SelectedIndex=3;}
    void EditProduct(Producto? existing){var form=new Form{Text=existing==null?"Nuevo producto":"Editar producto",Width=470,Height=440,StartPosition=FormStartPosition.CenterParent};var panel=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=9,Padding=new Padding(12)};panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,40));panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,60));form.Controls.Add(panel);        // Manual rows avoid designer dependencies
        panel.Controls.Clear();panel.RowCount=0;
        void Row(string label,Control control){panel.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left},0,panel.RowCount);panel.Controls.Add(control,1,panel.RowCount);panel.RowCount++;}
        var code=new TextBox{Text=existing?.Codigo??""};var name=new TextBox{Text=existing?.Nombre??""};var category=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};category.DataSource=Enum.GetValues<Categoria>();category.SelectedItem=existing?.Categoria??Categoria.ArenaGatos;var presentation=new TextBox{Text=existing?.Presentacion??""};var price=new NumericUpDown{Maximum=100000000,Minimum=1,Value=existing?.Precio??1000,DecimalPlaces=0};var stock=new NumericUpDown{Maximum=1000000,Value=existing?.Stock??0,Enabled=existing==null};var min=new NumericUpDown{Maximum=1000000,Value=existing?.StockMinimo??5};var active=new CheckBox{Checked=existing?.Activo??true,Text="Disponible"};Row("Código",code);Row("Nombre",name);Row("Categoría",category);Row("Presentación",presentation);Row("Precio CLP",price);Row("Stock inicial",stock);Row("Stock mínimo",min);Row("Estado",active);var save=Btn("Guardar",()=>{store.Guardar(new Producto(existing?.Id??0,code.Text,name.Text,(Categoria)category.SelectedItem!,presentation.Text,price.Value,(int)stock.Value,(int)min.Value,active.Checked));form.DialogResult=DialogResult.OK;form.Close();});panel.Controls.Add(save,1,panel.RowCount);form.AcceptButton=save;if(form.ShowDialog(this)==DialogResult.OK)RefreshAll();}
    void EditClient(Cliente? existing){var form=new Form{Text="Datos de cliente",Width=440,Height=330,StartPosition=FormStartPosition.CenterParent};var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(12)};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,32));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,68));form.Controls.Add(layout);TextBox Row(string label,string value){int n=layout.RowCount++;layout.Controls.Add(new Label{Text=label,AutoSize=true},0,n);var tb=new TextBox{Text=value,Dock=DockStyle.Fill};layout.Controls.Add(tb,1,n);return tb;}var n=Row("Nombre",existing?.Nombre??"");var d=Row("RUT/Documento",existing?.Documento??"");var t=Row("Teléfono",existing?.Telefono??"");var e=Row("Email",existing?.Email??"");var a=Row("Dirección",existing?.Direccion??"");var b=Btn("Guardar",()=>{store.Guardar(new Cliente(existing?.Id??0,n.Text,d.Text,t.Text,e.Text,a.Text));form.DialogResult=DialogResult.OK;form.Close();});layout.Controls.Add(b,1,layout.RowCount++);form.AcceptButton=b;if(form.ShowDialog(this)==DialogResult.OK)RefreshAll();}
    void Adjust(){var p=Selected<Producto>(products)??throw new InvalidOperationException("Seleccione un producto.");var input=Microsoft.VisualBasic.Interaction.InputBox($"Ajuste para {p.Nombre}. Ingrese +10 para entrada o -2 para salida:","Movimiento de stock","1");if(!int.TryParse(input,out var delta))return;var reason=Microsoft.VisualBasic.Interaction.InputBox("Motivo del ajuste:","Motivo","Reposición / corrección");store.Ajustar(p.Id,delta,reason);RefreshAll();}
    void ShowReceipt(){var v=Selected<VentaResumen>(sales)??throw new InvalidOperationException("Seleccione una venta.");var sb=new StringBuilder();sb.AppendLine("COMPROBANTE INTERNO - NO TRIBUTARIO").AppendLine($"Venta #{v.Id} | {v.Fecha:g}").AppendLine($"Cliente: {v.Cliente}").AppendLine($"Medio de pago: {v.MedioPago}").AppendLine(new string('-',48));foreach(var line in store.Detalle(v.Id))sb.AppendLine($"{line.Nombre}  {line.Cantidad} x ${line.PrecioUnitario:N0} = ${line.Subtotal:N0}");sb.AppendLine(new string('-',48)).AppendLine($"TOTAL: ${v.Total:N0}");using var dialog=new SaveFileDialog{Filter="Texto (*.txt)|*.txt",FileName=$"comprobante-{v.Id}.txt"};if(dialog.ShowDialog(this)==DialogResult.OK){File.WriteAllText(dialog.FileName,sb.ToString(),Encoding.UTF8);MessageBox.Show("Comprobante guardado.");}else MessageBox.Show(sb.ToString(),"Vista previa");}
    void ExportCsv(){using var dialog=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName="ventas.csv"};if(dialog.ShowDialog(this)!=DialogResult.OK)return;static string Esc(string x)=>"\""+x.Replace("\"","\"\"")+"\"";var rows=new List<string>{"ID;Fecha;Cliente;Pago;Total_CLP"};rows.AddRange(store.ListarVentas().Select(v=>$"{v.Id};{Esc(v.Fecha.ToString("yyyy-MM-dd HH:mm"))};{Esc(v.Cliente)};{Esc(v.MedioPago)};{v.Total.ToString(CultureInfo.InvariantCulture)}"));File.WriteAllLines(dialog.FileName,rows,Encoding.UTF8);MessageBox.Show("CSV exportado.");}
}
